def evaluate(
    current_reputation: float,
    observation: dict,
    my_history: list[dict],
    round_num: int
) -> float:
    # Reciprocal evaluation: if donor helped a high-reputation recipient, reward more
    # But we don't see recipient's reputation in observation? We have only current_reputation of donor.
    # So we can't directly condition on recipient reputation. We'll just use a simple update.
    # For this strategy, we make evaluation asymmetric:
    # Donating to someone: +0.2; Not donating: -0.1
    if observation["action"] == "donate":
        return max(-1.0, min(1.0, current_reputation + 0.2))
    else:
        return max(-1.0, min(1.0, current_reputation - 0.1))

def decide(
    recipient_reputation: float,
    round_num: int,
    my_history: list[dict]
) -> bool:
    # donate if recipient reputation > 0 (i.e., generally good)
    return recipient_reputation > 0.0

